import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Tra storia e leggenda","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/b_aritmetica-e-numeri/bb/bba1.md","filePath":"lezioni/b_aritmetica-e-numeri/bb/bba1.md"}`),a={name:`lezioni/b_aritmetica-e-numeri/bb/bba1.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="tra-storia-e-leggenda" tabindex="-1">Tra storia e leggenda <a class="header-anchor" href="#tra-storia-e-leggenda" aria-label="Permalink to “Tra storia e leggenda”">​</a></h1><p>Nel bacino del Mediterraneo nel primo millennio avanti Cristo i Fenici fondarono la loro fortuna sul commercio di tessuti che solo essi sapevano colorare di porpora utilizzando un particolare mollusco.</p><p>Va a sé che solamente i capi dei villaggi ed i grandi sacerdoti potevano acquistare tali stoffe e quindi in tutto il mediterraneo il colore rosso venne associato al concetto di comando: i cavalieri romani avevano i mantelli color porpora ed i senatori avevano sulle candide toghe una striscia rossa; ancor oggi quando i cardinali siedono in conclave sono vestiti di rosso (rosso cardinale o rosso porpora).</p><p>Alla decadenza dell&#39;impero romano il concetto di rosso rimase comunque associato al concetto di comando.</p><p>Venne il Medio Evo ed attorno al 1100 a Firenze divennero una potenza i banchieri che, dovendo tenere i conti, scrivevano sui loro libri in nero le cifre da ricevere ed in rosso le cifre da pagare (ancor oggi spendere più di quello che si ha è detto &quot;andare in rosso&quot;).</p><p>Attorno al 1170, Federico Barbarossa, per ridare autorità all&#39;impero fra gli altri editti ne emise uno che riservava il colore rosso solamente per gli editti imperiali e non poteva essere usato per altri documenti, ai trasgressori sarebbe stata tagliata la testa.</p><p>Disperazione dei banchieri i quali dovettero quindi trovare un sistema diverso per tenere i conti e sembra che qualcuno propose di mettere davanti ai numeri un segno <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>+</mo></mrow><annotation encoding="application/x-tex">+</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">+</span></span></span></span> per le cifre da avere ed un segno <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>−</mo></mrow><annotation encoding="application/x-tex">-</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">−</span></span></span></span> per le cifre da pagare.</p><p>Infine, vista la facilità con cui si potevano falsificare i conti, prevalse il sistema di utilizzare due colonne: una per le cifre da pagare e l&#39;altra per le cifre da ricevere (la partita doppia).</p><p>Comunque era nata la rappresentazione dei numeri interi che conosciamo noi, anche se prima di utilizzare tale rappresentazione dovranno passare altri <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>4</mn></mrow><annotation encoding="application/x-tex">4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span> secoli.</p>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};